(5182524, 753433, 56744, '<td valign="top">True love is not about the hugs and kisses, the ''I love you''s'' or the ''I miss you''s'', but about the how high someone will climb to reach you. You already won this challenge cause you really are a lucky guy.</td>', 'True love is not about the hugs and kisses, the ''I love you''s'' or the ''I miss you''s'', but about the how high someone will climb to reach you. You already won this challenge cause you really are a lucky guy.', '2009-01-09 18:24:25.000000', NULL, 1),
(5182543, 753363, 83313, '<td valign="top">Like the idea, but this photo of it seems like a snapshot. At a filesize of 83k you may have some JPEG compression robbing a some of the original clarity.</td>', 'Like the idea, but this photo of it seems like a snapshot. At a filesize of 83k you may have some JPEG compression robbing a some of the original clarity.', '2009-01-09 18:40:12.000000', NULL, 1),
