(5190245, 752277, 78455, '<td valign="top">Congratulations on a top 30 finish with your first DPC entry! Hope to see a lot more from you in the coming challenges! :-)</td>', 'Congratulations on a top 30 finish with your first DPC entry! Hope to see a lot more from you in the coming challenges! :-)', '2009-01-14 05:15:31.000000', NULL, 0),
(5190260, 753036, 72134, '<td valign="top">Thanks for your votes. I was becoming desperate, since I couldn''nt find any lucky person around here. So when i was driving by this waterfall, which is located close to the highway and saw some tourists photographing there on nice weather so I took a few shots whith this result, I am pleased with nr. 6</td>', 'Thanks for your votes. I was becoming desperate, since I couldn''nt find any lucky person around here. So when i was driving by this waterfall, which is located close to the highway and saw some tourists photographing there on nice weather so I took a few shots whith this result, I am pleased with nr. 6', '2009-01-14 05:21:12.000000', NULL, 0),
(5190299, 753650, 92864, '<td valign="top">Pretty cool! Congrats on another ribbon ;)</td>', 'Pretty cool! Congrats on another ribbon ;)', '2009-01-14 05:52:32.000000', NULL, 0),
