(5190309, 753201, 70661, '<td valign="top">Congrats! Very nice!</td>', 'Congrats! Very nice!', '2009-01-14 05:58:21.000000', NULL, 0),
(5190322, 753650, 52549, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> You''re a maniac.  I love the bit about your husband wondering if you needed help then most likely quietly backing away and standing by (out of your view) with the fire extinguisher, just in case!  Beautifully lit and shot as always - you do seem to have such fun thinking these things up then executing them, and I really appreciate the fact you share your process with us.  (And you made Ken happy - fire!!!) </i></td></tr></table> <br/>LOL! If Ken''s happy, I am too!</td>', 'Originally posted by Melethia: You''re a maniac.  I love the bit about your husband wondering if you needed help then most likely quietly backing away and standing by (out of your view) with the fire extinguisher, just in case!  Beautifully lit and shot as always - you do seem to have such fun thinking these things up then executing them, and I really appreciate the fact you share your process with us.  (And you made Ken happy - fire!!!)  LOL! If Ken''s happy, I am too!', '2009-01-14 06:23:20.000000', NULL, 0),
(5190391, 753433, 38127, '<td valign="top">Wooo Hoooo!!!!!!!!!!!! Congrats on your first ribbon sweets.. well done ;) you are a romantical kinda guy and it worked for ya!!! Cheek smooches!!! :) :) :)</td>', 'Wooo Hoooo!!!!!!!!!!!! Congrats on your first ribbon sweets.. well done ;) you are a romantical kinda guy and it worked for ya!!! Cheek smooches!!! :) :) :)', '2009-01-14 07:37:09.000000', NULL, 0),
(5190400, 753433, 79955, '<td valign="top">Heck of a shot!! Congrats on the ribbon.</td>', 'Heck of a shot!! Congrats on the ribbon.', '2009-01-14 07:59:03.000000', NULL, 0),
(5190415, 752277, 102021, '<td valign="top">nice shot!....but a lil exposure and contrast would''ve really made a world of difference!......great job!....love the idea!....its almost the shape of a heart with the birds perched together...u got a lucky shot there!:)....</td>', 'nice shot!....but a lil exposure and contrast would''ve really made a world of difference!......great job!....love the idea!....its almost the shape of a heart with the birds perched together...u got a lucky shot there!:)....', '2009-01-14 08:16:09.000000', NULL, 0),
(5190490, 753650, 75034, '<td valign="top">OK you, CONGRATULATIONS on your 40th ribbon and now that you have twice as many ribbons as your age don''t you think it''s time to let someone else get a few?<br/> <br/>WOW 40 ribbons you must be grinning like a fool right now. <br/> <br/>I do hope to see many more ribbons come your way and I do wish you all the best. You have so much talent and I''m glad your sharing it with us.<br/> <br/>Thank you Irene for all the wonderful images you have given us over the years :)<br/> <br/>All the best to you and yours.<br/> <br/>MAX!</td>', 'OK you, CONGRATULATIONS on your 40th ribbon and now that you have twice as many ribbons as your age don''t you think it''s time to let someone else get a few? WOW 40 ribbons you must be grinning like a fool right now.  I do hope to see many more ribbons come your way and I do wish you all the best. You have so much talent and I''m glad your sharing it with us. Thank you Irene for all the wonderful images you have given us over the years :) All the best to you and yours. MAX!', '2009-01-14 08:49:55.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5190551, 753650, 52115, '<td valign="top">Hot shot!<br/>Well at least you didn''t burn down the house or your village.<br/>Was it done indoors or outside?</td>', 'Hot shot!Well at least you didn''t burn down the house or your village.Was it done indoors or outside?', '2009-01-14 09:10:05.000000', NULL, 0),
(5190577, 753650, 61961, '<td valign="top">Congratulations, Irene.  Well done!</td>', 'Congratulations, Irene.  Well done!', '2009-01-14 09:16:09.000000', NULL, 0),
(5190598, 753433, 52115, '<td valign="top">You''re getting better all the time.<br/>Sounds like the 24-70mm would''ve worked better. At 1/250 5.6 you may not need the camera on a tripod, or is there an advantage?<br/> <br/>Anyways it''s alway part skill, persistance, innovation, along with luck. It turned out great.</td>', 'You''re getting better all the time.Sounds like the 24-70mm would''ve worked better. At 1/250 5.6 you may not need the camera on a tripod, or is there an advantage? Anyways it''s alway part skill, persistance, innovation, along with luck. It turned out great.', '2009-01-14 09:18:45.000000', NULL, 0),
(5190609, 753344, 20748, '<td valign="top">I find the title rather humorous.  There are plenty of stereotypes out there. If you spend your time getting offended by the internet, it''s your own fault. Grow some thicker skin.</td>', 'I find the title rather humorous.  There are plenty of stereotypes out there. If you spend your time getting offended by the internet, it''s your own fault. Grow some thicker skin.', '2009-01-14 09:26:23.000000', NULL, 0),
(5190616, 753433, 67579, '<td valign="top">Great job Cory, grats on the ribbon! well deserved :)</td>', 'Great job Cory, grats on the ribbon! well deserved :)', '2009-01-14 09:30:18.000000', NULL, 0),
(5190632, 753433, 30791, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by justamistere:</b></div><hr/><i> You''re getting better all the time.<br/>Sounds like the 24-70mm would''ve worked better. At 1/250 5.6 you may not need the camera on a tripod, or is there an advantage?<br/> <br/>Anyways it''s alway part skill, persistance, innovation, along with luck. It turned out great. </i></td></tr></table> <br/>Yes Sir thanks for the compliments, the tripod was needed, I had to be in the picture too! I just used a remote to trip the shutter</td>', 'Originally posted by justamistere: You''re getting better all the time.Sounds like the 24-70mm would''ve worked better. At 1/250 5.6 you may not need the camera on a tripod, or is there an advantage? Anyways it''s alway part skill, persistance, innovation, along with luck. It turned out great.  Yes Sir thanks for the compliments, the tripod was needed, I had to be in the picture too! I just used a remote to trip the shutter', '2009-01-14 09:33:44.000000', NULL, 0),
